package org.melavo.probe;
public final class ProbeActivity extends android.app.Activity {public void onCreate(android.os.Bundle state){super.onCreate(state);new Thread(()->{try(java.net.Socket socket=new java.net.Socket()){socket.connect(new java.net.InetSocketAddress("198.18.0.1",8080),15000);socket.setSoTimeout(15000);socket.getOutputStream().write("GET / HTTP/1.1\r\nHost: melavo.test\r\nConnection: close\r\n\r\n".getBytes(java.nio.charset.StandardCharsets.US_ASCII));byte[] bytes=new byte[4096];java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();int n;while((n=socket.getInputStream().read(bytes))!=-1)out.write(bytes,0,n);if(!out.toString("UTF-8").contains("melavo-tun-proof"))throw new Exception("Wrong response");sendBroadcast(new android.content.Intent("org.melavo.probe.RESULT").setPackage("org.melavo.vpn").putExtra("success",true));android.util.Log.i("MelavoProbe","PASS: TUN traffic reached the private test server");}catch(Exception e){android.util.Log.e("MelavoProbe","FAIL: "+e);}finally{runOnUiThread(this::finish);}}).start();}}
